INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱祁镇", "aliases": ["明英宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明英宗，宣德10年（1435年）正月，朱祁镇即皇帝位。", "biography": null, "status": "draft", "id": "368e5a42-621f-5c8c-88c7-f59b8bb8a5cf"}, {"name": "陈文", "aliases": ["陳文"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，天順7年（1463年）二月，陈文升任礼部右侍郎，兼翰林学士并入阁。", "biography": null, "status": "draft", "id": "8f83c83c-067e-5973-b22d-64cf8d768a2f"}, {"name": "胡善祥", "aliases": ["恭让章皇后"], "era": "明", "birth_year": null, "death_year": null, "description": "胡善祥被立为皇后。", "biography": null, "status": "draft", "id": "899c42d7-6f22-5ca0-a482-61161e914b39"}, {"name": "宋钦", "aliases": ["宋欽"], "era": "明", "birth_year": null, "death_year": null, "description": "宋钦梧州失守时遇害。", "biography": null, "status": "draft", "id": "c4d76feb-6fd8-5a78-90a8-cc8750401cb0"}, {"name": "李宾", "aliases": ["李賓"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，天顺5年（年号对照1461年）七月，李宾出任右都御史。", "biography": null, "status": "draft", "id": "35ff77e9-c438-51b2-a731-d9b2a1dabed9"}, {"name": "林聪", "aliases": ["林聰"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，成化3年（年号对照1467年）四月，林聪出任右都御史。", "biography": null, "status": "draft", "id": "ca5f4f12-f595-598a-b3e3-ff0f69ba7def"}, {"name": "陆瑜（明代官员）", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，天顺2年（年号对照1458年）十月，陆瑜由布政使升任刑部尚书。", "biography": null, "status": "draft", "id": "f1e8b6e8-e2c8-5043-a450-d41c6d5636db"}, {"name": "周瑄", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，天顺7年（年号对照1463年）二月，周瑄以刑部侍郎身份代理工部尚书事务。", "biography": null, "status": "draft", "id": "ea1ac555-526a-5271-90f3-3a835a44bcb0"}, {"name": "程信（明代官员）", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，成化4年（年号对照1468年）四月，程信从四川返回兵部。", "biography": null, "status": "draft", "id": "24bdbf76-7b38-5aee-bea5-83d1a49f29dc"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "明英宗在南郊祭祀天地", "description": "天顺七年正月丙午，明英宗朱祁镇在南郊举行祭祀天地的大典。", "start_year": 1463, "end_year": 1463, "time_original": "天顺七年正月丙午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8d8bf9ec-9986-566a-a74f-c6e940c7ad35"}, {"title": "陈文升任礼部右侍郎，兼翰林学士并入阁", "description": "天順7年（1463年）二月，陈文升任礼部右侍郎，兼翰林学士并入阁。", "start_year": 1463, "end_year": 1463, "time_original": "天順7年（1463年）二月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "110d132b-bbee-5ab3-8b76-5dc2762782da"}, {"title": "明廷因旱诏行宽恤措施，暂停各处银场", "description": "天顺七年三月壬寅，朝廷因旱下诏，施行减轻负担、体恤百姓的措施，并暂停各处银场。", "start_year": 1463, "end_year": 1463, "time_original": "天顺七年三月壬寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bfb8b3db-d110-5d01-a220-2eb40cb74c88"}, {"title": "御史李蕃被捕，在长安门枷示后去世", "description": "天顺七年四月壬午，巡按宣府、大同的御史李蕃被捕，在长安门戴枷示众。不久，李蕃去世。", "start_year": 1463, "end_year": 1463, "time_original": "天顺七年四月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "86bbac0f-e721-57ab-a0b9-6b93fbb25acf"}, {"title": "明廷再次派宦官督办苏州和杭州织造", "description": "天顺七年四月丙戌，明廷再次派遣宦官到苏州和杭州督办织造。", "start_year": 1463, "end_year": 1463, "time_original": "天顺七年四月丙戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ec063323-6c0d-5119-a102-4001a39ab382"}, {"title": "本纪记天顺七年五月初一发生日食", "description": "天顺七年五月初一，《英宗后纪》记发生日食。", "start_year": 1463, "end_year": 1463, "time_original": "天顺七年五月己丑朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cf034af8-879e-5442-a80f-2127bd931378"}, {"title": "辽东巡按御史杨琎因擅自体罚武官被捕", "description": "天顺七年五月甲寅，辽东巡按御史杨琎被指擅自体罚有军职者，遭到拘捕查办。", "start_year": 1463, "end_year": 1463, "time_original": "天顺七年五月甲寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9c16cda4-8fb2-5246-8c22-7483470f00ee"}, {"title": "御史韩祺被捕，在长安门枷示后去世", "description": "天顺七年六月丁卯，山西巡按御史韩祺被捕，在长安门戴枷示众，数日后去世。", "start_year": 1463, "end_year": 1463, "time_original": "天顺七年六月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d0fc8676-effb-57f3-92d8-6b1a00299734"}, {"title": "明廷豁免陕西灾区税粮", "description": "天顺七年七月庚戌，朝廷免除陕西受灾地区应缴的税粮。", "start_year": 1463, "end_year": 1463, "time_original": "天顺七年七月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b409593b-54a4-561b-b1cb-51b1f3a57e52"}, {"title": "明廷为宣宗原皇后胡善祥上尊谥", "description": "天顺七年闰七月甲戌，明廷为被明宣宗废去皇后身份的胡善祥上尊谥。《后妃传》载尊谥为恭让诚顺康穆静慈章皇后。", "start_year": 1463, "end_year": 1463, "time_original": "天顺七年闰七月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cfdca8ec-d2cc-5160-a45b-50707c4117f2"}, {"title": "明廷命湖广和贵州合兵征讨洪江起事苗民", "description": "天顺七年闰七月戊寅，朝廷命湖广、贵州的军队会合，征讨洪江的起事苗民。", "start_year": 1463, "end_year": 1463, "time_original": "天顺七年闰七月戊寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7babcd89-c173-5d09-9f00-a5759690aa3b"}, {"title": "明廷命欧信会同广西兵力征讨起事瑶民", "description": "天顺七年九月甲戌，明廷下敕，命广东总兵官欧信会合广西的部队，征讨起事的瑶民。", "start_year": 1463, "end_year": 1463, "time_original": "天顺七年九月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b82865f2-639b-59d9-853b-8d71ddc224a7"}, {"title": "明廷赈济西安等府的饥民", "description": "天顺七年十月丁酉，朝廷赈济西安等府的饥民。", "start_year": 1463, "end_year": 1463, "time_original": "天顺七年十月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8a2ef097-a75a-543c-a4ee-9d42f5f4293e"}, {"title": "明廷命吴桢节制两广军队，征讨起事瑶民", "description": "天顺七年十月丁未，朝廷命巡抚广西的佥都御史吴桢节制两广部队，征讨起事的瑶民。", "start_year": 1463, "end_year": 1463, "time_original": "天顺七年十月丁未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b0bb9009-f1f6-548a-8c6e-a807fb820f75"}, {"title": "梧州失守，已经退休的布政使宋钦遇害", "description": "天顺七年十一月癸酉，起事武装攻陷梧州，已经退休的布政使宋钦遇害。", "start_year": 1464, "end_year": 1464, "time_original": "天顺七年十一月癸酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e42a7026-7cf0-5e12-8b77-7cb76faafe6c"}, {"title": "李宾、林聪被关入锦衣卫监狱", "description": "天顺七年十一月壬午，明廷将右都御史李宾和副都御史林聪关入锦衣卫监狱。", "start_year": 1464, "end_year": 1464, "time_original": "天顺七年十一月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "eb64c850-9599-527a-bcf4-c4e0826c4421"}, {"title": "陆瑜被投入监狱，不久获释", "description": "天顺7年（年号对照1463年）十二月，陆瑜被投入监狱，不久获释。按原历月份对照，这项行动发生在公元1464年。", "start_year": 1464, "end_year": 1464, "time_original": "天顺7年（年号对照1463年）十二月；公元年核为1464年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "c9014851-af1e-5264-b046-28b954044f43"}, {"title": "琉球中山、哈密、安南和乌斯藏入贡", "description": "天顺七年，琉球中山、哈密、安南和乌斯藏向明廷进贡。 按原历纪年，事情发生在公元1463至1464年之间。", "start_year": null, "end_year": null, "time_original": "天顺七年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cc2d8d6c-f564-5192-9b7b-4b82ea0f96b3"}]'::jsonb)
